<?php defined( 'ABSPATH' ) || exit; ?>
<?php if ( $show( 'show_paid_date' ) && ( $invoice->fulfillment['payment_confirmed'] ?? false ) && ! empty( $invoice->order['paid_date'] ) ) : ?><p><strong><?php esc_html_e( 'Payment date', 'wc-invoice-printer' ); ?>:</strong> <?php echo esc_html( $invoice->order['paid_date'] ); ?></p><?php endif; ?>
<?php if ( $show( 'show_shipping_phone' ) && ( $invoice->customer['shipping_phone'] ?? '' ) ) : ?><p><strong><?php esc_html_e( 'Recipient phone', 'wc-invoice-printer' ); ?>:</strong> <bdi dir="ltr"><?php echo esc_html( $invoice->customer['shipping_phone'] ); ?></bdi></p><?php endif; ?>
<?php if ( $show( 'show_recipient_extras' ) ) : foreach ( $invoice->customer['recipient']['extra'] ?? array() as $name => $value ) : ?><p><?php echo esc_html( $name . ': ' . $value ); ?></p><?php endforeach; endif; ?>
